from math import gcd

def transform(grid):
    h, w = len(grid), len(grid[0])
    blocks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not blocks:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in blocks), max(r for r, c in blocks)
    c0, c1 = min(c for r, c in blocks), max(c for r, c in blocks)
    runs = []
    for r in range(r0, r1 + 1):
        n = 0
        for c in range(c0, c1 + 2):
            if c <= c1 and grid[r][c] == 8: n += 1
            elif n: runs.append(n); n = 0
    for c in range(c0, c1 + 1):
        n = 0
        for r in range(r0, r1 + 2):
            if r <= r1 and grid[r][c] == 8: n += 1
            elif n: runs.append(n); n = 0
    unit = 0
    for n in runs: unit = gcd(unit, n)
    if unit == 0: return [row[:] for row in grid]
    key = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    if not key: return [row[:] for row in grid]
    kr0, kr1 = min(r for r, c in key), max(r for r, c in key)
    kc0, kc1 = min(c for r, c in key), max(c for r, c in key)
    # Rotate the colored key clockwise; each key cell maps to one unit-sized tile.
    key_grid = [[grid[r][c] for c in range(kc0, kc1 + 1)] for r in range(kr0, kr1 + 1)]
    rotated = [list(row) for row in zip(*key_grid[::-1])]
    out = [row[:] for row in grid]
    for tr in range((r1 - r0 + 1) // unit):
        for tc in range((c1 - c0 + 1) // unit):
            rr, cc = r0 + tr * unit, c0 + tc * unit
            if grid[rr][cc] != 8: continue
            color = rotated[tr][tc]
            for dr in range(unit):
                for dc in range(unit):
                    if grid[rr + dr][cc + dc] == 8:
                        out[rr + dr][cc + dc] = color
    return out
